/* ORDER BY TURA — frontend-only interactive prototype. No payments, shipping or authentication is real. */
(() => {
'use strict';
const $ = (q, root=document) => root.querySelector(q);
const KEY = 'tura-prototype-v3';
const ADMIN_SESSION = 'tura-demo-admin-session';
const fmt = n => new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(Number(n)||0) + 'đ';
const yuan = n => '¥' + new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(Number(n)||0);
const approxVnd = cny => '≈ ' + fmt(Math.round((Number(cny)||0) * db.settings.rate));
const priceTag = (cny, className='') => `<span class="price-pair ${className}"><strong class="price-cny">${yuan(cny)}</strong><span class="price-vnd">${approxVnd(cny)}</span></span>`;
const dateFormat = iso => { try { return new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(iso)); }catch{return '—';} };
const safe = x => String(x??'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ID = () => 'TURA-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
const clone = o => JSON.parse(JSON.stringify(o));
const now = () => new Date().toISOString();
const P = [
 {id:'1001001',name:'Túi đeo chéo gấu trúc mini',price:39.8,kind:'Túi / màu kem',emoji:'👜',weight:.25},
 {id:'1001002',name:'Cốc sứ phong cách tối giản',price:27.5,kind:'Cốc / trắng',emoji:'☕',weight:.55},
 {id:'1001003',name:'Bộ tất họa tiết dễ thương',price:18.9,kind:'Tất / Freesize',emoji:'🧦',weight:.15},
 ];
const stages = {
 new:['Đã gửi yêu cầu','orange'],reviewing:['Đang kiểm tra sản phẩm','blue'],needs_info:['Cần bổ sung thông tin','red'],out_of_stock:['Sản phẩm hết hàng','red'],
 quoted:['Chờ bạn xác nhận báo giá','purple'],awaiting_payment:['Chờ thanh toán','orange'],payment_review:['Đang kiểm tra thanh toán','blue'],
 paid:['Đã xác nhận thanh toán','green'],buying:['Tura đang mua hàng','blue'],china_shipping:['Đang vận chuyển tại Trung Quốc','blue'],
 international_shipping:['Đang vận chuyển về Việt Nam','blue'],vietnam_warehouse:['Đã về kho Việt Nam','green'],
 delivering:['Đang giao đến bạn','blue'],completed:['Hoàn tất','green'],cancelled:['Đã hủy','gray']
};
const nextAdmin = {
 new:[['reviewing','Bắt đầu kiểm tra']],reviewing:[],needs_info:[['reviewing','Tiếp tục kiểm tra']],out_of_stock:[['reviewing','Kiểm tra lại']],
 quoted:[['reviewing','Sửa báo giá']],awaiting_payment:[],payment_review:[['paid','Xác nhận đã nhận tiền'],['awaiting_payment','Yêu cầu kiểm tra lại']],
 paid:[['buying','Bắt đầu mua hàng']],buying:[['china_shipping','Hàng đang vận chuyển tại Trung Quốc']],
 china_shipping:[['international_shipping','Bắt đầu vận chuyển về Việt Nam']],international_shipping:[['vietnam_warehouse','Đã về kho Việt Nam']],
 vietnam_warehouse:[['delivering','Bắt đầu giao hàng']],delivering:[['completed','Hoàn tất đơn']]
};
const defaultSettings = {rate:3700,service:20000,chinaShip:15000,internationalShip:30000};
const defaultSocial = {facebook:'',instagram:''};
function seed() {
 const demoItem={...P[0],link:'https://item.taobao.com/item.htm?id=1001001',qty:1,color:'Kem',size:'Nhỏ',note:''};
 const item2={...P[2],link:'https://item.taobao.com/item.htm?id=1001003',qty:2,color:'Cam',size:'Freesize',note:''};
 const t = new Date();
 const ago = hrs => new Date(t.getTime()-hrs*3600000).toISOString();
 return {cart:[],settings:clone(defaultSettings),social:clone(defaultSocial),orders:[
  {id:'TURA-DEMO-001',sample:true,createdAt:ago(8),updatedAt:ago(3),customer:{name:'Nguyễn An (mẫu)',phone:'0900 000 001',address:'Địa chỉ nhận hàng mẫu, TP.HCM',note:'Đơn mô phỏng quy trình'},items:[demoItem],estimate:212260,status:'china_shipping',quote:{products:147260,service:20000,chinaShip:15000,internationalShip:30000,other:0,total:212260},payment:'confirmed',tracking:'CN-DEMO-001',publicNote:'Kiện hàng đang được vận chuyển nội địa Trung Quốc.',history:[{status:'new',note:'Đã gửi yêu cầu đặt hộ.',at:ago(8)},{status:'reviewing',note:'Tura bắt đầu kiểm tra sản phẩm.',at:ago(7.5)},{status:'quoted',note:'Tura đã gửi báo giá.',at:ago(7)},{status:'awaiting_payment',note:'Khách đã xác nhận báo giá.',at:ago(6.5)},{status:'payment_review',note:'Khách đã thông báo chuyển khoản.',at:ago(6)},{status:'paid',note:'Tura xác nhận thanh toán (mô phỏng).',at:ago(5.5)},{status:'buying',note:'Tura bắt đầu mua hàng.',at:ago(4)},{status:'china_shipping',note:'Kiện hàng được giao tại Trung Quốc (mô phỏng).',at:ago(3)}]},
  {id:'TURA-DEMO-002',sample:true,createdAt:ago(4),updatedAt:ago(4),customer:{name:'Trần Bình (mẫu)',phone:'0900 000 002',address:'Địa chỉ mẫu, Hà Nội',note:''},items:[item2],status:'new',estimate:204860,quote:null,payment:'unpaid',tracking:'',publicNote:'',history:[{status:'new',note:'Đã gửi yêu cầu đặt hộ.',at:ago(4)}]}
 ]};
}
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x && Array.isArray(x.cart) && Array.isArray(x.orders) && x.settings)return x;}catch{}return seed();}
let db=load();
db.social={...defaultSocial,...(db.social||{})};
const ui={page:'home',modal:null,detail:null,adminTab:'dashboard',adminOrder:null,adminSearch:'',adminFilter:'all',ordersQuery:'',selectedImage:0};
let toastTimer;
function store(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('Không lưu được vào trình duyệt. Kiểm tra dung lượng bộ nhớ.');}}
function toast(t){const el=$('#toast');if(!el)return;el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400);}
function estimation(items=db.cart){const products=items.reduce((s,p)=>s+p.price*p.qty*db.settings.rate,0);const chinaShip=items.length?db.settings.chinaShip:0;const internationalShip=items.length?db.settings.internationalShip:0;const service=items.length?db.settings.service:0;return {products:Math.round(products),chinaShip,internationalShip,service,other:0,total:Math.round(products+chinaShip+internationalShip+service)};}
function productUrl(link){try{const m=String(link).match(/https?:\/\/[^\s<>"']+/);if(!m)return null;const u=new URL(m[0]);const domains=['taobao.com','tmall.com','1688.com','m.tb.cn'];if(!['http:','https:'].includes(u.protocol)||!domains.some(d=>u.hostname===d||u.hostname.endsWith('.'+d)))return null;return u.href;}catch{return null;}}
function presetForLink(url){try{const id=new URL(url).searchParams.get('id');return P.find(p=>p.id===id);}catch{return null;}}
function status(code){const [label,color]=stages[code]||['Không xác định','gray'];return `<span class="status ${color}">${safe(label)}</span>`;}
function timeline(history){return `<ol class="timeline">${[...history].reverse().map((h,i)=>`<li class="${i>4?'is-muted':''}"><div class="circle">${i===0?'✓':'•'}</div><div><strong>${safe(stages[h.status]?.[0]||h.status)}</strong><time>${dateFormat(h.at)}</time><p>${safe(h.note||'Trạng thái đã được cập nhật.')}</p></div></li>`).join('')}</ol>`;}
function log(o,s,note){o.status=s;o.updatedAt=now();o.history=o.history||[];o.history.push({status:s,note,at:o.updatedAt});store();}
function findOrder(id){return db.orders.find(o=>o.id===id);}
function moneyRows(e){return `<div class="money-row"><span>Tiền hàng quy đổi</span><strong>${fmt(e.products)}</strong></div><div class="money-row"><span>Phí dịch vụ</span><strong>${fmt(e.service)}</strong></div><div class="money-row"><span>Vận chuyển nội địa Trung Quốc</span><strong>${fmt(e.chinaShip)}</strong></div><div class="money-row"><span>Vận chuyển Trung Quốc – Việt Nam</span><strong>${fmt(e.internationalShip)}</strong></div>${e.other?`<div class="money-row"><span>Phí khác</span><strong>${fmt(e.other)}</strong></div>`:''}<hr class="divider"><div class="grand-total"><span>Tổng cộng</span><strong>${fmt(e.total)}</strong></div>`;}
function orderMoney(o){return o.quote||{...estimation(o.items),total:o.estimate||0};}
function productRows(items){return `<div class="order-items">${items.map(p=>`<div class="order-line"><div class="product-tile">${safe(p.emoji||'📦')}</div><div><h4>${safe(p.name)}</h4><p>${safe([p.color,p.size].filter(Boolean).join(' • ')||'Chưa chọn phân loại')} · SL: ${p.qty}</p><a class="product-url text-link" href="${safe(p.link)}" target="_blank" rel="noopener noreferrer">Link sản phẩm Taobao ↗</a></div><div class="order-price">${priceTag(p.price*p.qty)}</div></div>`).join('')}</div>`;}
function socialUrl(value,network){
 try{
  if(!value)return '';
  const u=new URL(value);
  const domains=network==='facebook'?['facebook.com','fb.com','fb.me']:['instagram.com'];
  if(u.protocol!=='https:'||!domains.some(d=>u.hostname===d||u.hostname.endsWith('.'+d)))return '';
  return u.href;
 }catch{return '';}
}
function socialCard(network,title,handle,icon){
 const link=socialUrl(db.social?.[network],network);
 return link?`<a class="social-card active" href="${safe(link)}" target="_blank" rel="noopener noreferrer" aria-label="Mở ${title} Tura trong tab mới"><span class="social-icon ${network}">${icon}</span><span class="social-card-text"><strong>${title}</strong><small>${handle}</small></span><span class="social-arrow">↗</span></a>`:`<button type="button" class="social-card is-soon" data-act="soon" data-channel="${network}"><span class="social-icon ${network}">${icon}</span><span class="social-card-text"><strong>${title}</strong><small>Sắp cập nhật liên kết</small></span><span class="social-coming">Sắp có</span></button>`;
}
function header(){return `<div class="top-strip"><span class="top-spark">✳</span> <strong>ORDER BY TURA</strong> <span>· Đặt hộ hàng Taobao, thật dễ cùng gấu Tura</span> <span class="top-demo">Bản trải nghiệm · Không xử lý đơn thật</span></div><header class="site-header"><div class="shell header-inner"><a class="brand-link" href="#home" data-go="home" aria-label="ORDER BY TURA - Trang chủ"><img src="./logo.svg" alt="ORDER BY TURA"></a><nav class="nav-links" aria-label="Điều hướng chính">${[['home','Trang chủ'],['cart','Giỏ hàng'],['orders','Đơn hàng'],['guide','Hướng dẫn']].map(([id,t])=>`<button data-go="${id}" class="${ui.page===id||ui.page==='order'&&id==='orders'?'active':''}">${t}${id==='cart'&&db.cart.length?` <span class="pill-count">${db.cart.length}</span>`:''}</button>`).join('')}</nav><div class="header-right"><button class="btn secondary sm" data-go="admin">Quản trị <span aria-hidden="true">↗</span></button></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="shell footer-inner footer-redesign"><div class="footer-brand"><img src="./logo.svg" alt="ORDER BY TURA"><p>Đồ xinh trên Taobao, để Tura lo.<br><span>Website đang trong giai đoạn trải nghiệm giao diện.</span></p></div><div class="footer-right"><div class="footer-actions"><button data-go="guide">Hướng dẫn đặt hàng</button><button data-go="orders">Theo dõi đơn</button><button data-go="admin">Admin</button></div><div class="footer-meta"><span>© 2026 ORDER BY TURA · Prototype</span><button data-act="reset">Đặt lại dữ liệu demo</button></div></div></div></footer>`;}
function home(){return `<div class="shell landing"><section class="hero tura-hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="hero-kicker"><span class="sparkle">✳</span> Đặt hàng Taobao cùng Tura</div><h1 id="hero-title">Đồ xinh trên <em>Taobao</em>,<br>để <span class="tura-highlight">gấu Tura</span> lo!</h1><p>Bạn tìm món yêu thích, Tura giúp kiểm tra giá, đặt hộ và theo dõi hành trình hàng về Việt Nam.</p><form id="hero-link" class="hero-form"><span aria-hidden="true" class="link-glyph">↗</span><input id="link-input" name="link" aria-label="Dán liên kết sản phẩm Taobao, Tmall hoặc 1688" placeholder="Dán link sản phẩm Taobao tại đây..." required autocomplete="off"><button class="btn" type="submit">Bắt đầu đặt hộ <span aria-hidden="true">→</span></button></form><div class="hero-hint"><span class="hint-star">✦</span> Đang ở bản demo? Hãy thử sản phẩm mẫu bên dưới nhé.</div><div class="hero-trust"><span><i aria-hidden="true">✓</i> Dễ thao tác</span><span><i aria-hidden="true">✓</i> Chi phí rõ ràng</span><span><i aria-hidden="true">✓</i> Theo dõi từng chặng</span></div></div><div class="hero-visual"><span class="visual-spark visual-spark-one">✦</span><span class="visual-spark visual-spark-two">✳</span><img class="hero-mascot" src="./tura-mascot.webp" width="1000" height="1000" alt="Linh vật gấu trúc Tura đội mũ cam, đẩy xe hàng Taobao đầy những kiện hàng" fetchpriority="high"><div class="hero-floating floating-top"><span>✦</span> Tura nhận order!</div><div class="hero-floating floating-bottom"><span>📦</span> Về Việt Nam cùng Tura</div></div></section><div class="landing-benefits"><div><span class="benefit-icon">↗</span><strong>Chỉ cần gửi link</strong><small>Taobao · Tmall · 1688</small></div><div><span class="benefit-icon">◈</span><strong>Báo giá trước khi mua</strong><small>Xem rõ từng khoản phí</small></div><div><span class="benefit-icon">◎</span><strong>Luôn biết hàng ở đâu</strong><small>Cập nhật theo từng chặng</small></div></div><section class="content-section how-section" id="how-it-works"><div class="section-head"><div><div class="section-label">Cách Tura hoạt động</div><h2>Đặt hàng nhẹ tênh, chỉ 4 bước</h2><p>Mọi thứ được trình bày đơn giản, từ lúc gửi link tới lúc nhận hàng.</p></div><button data-go="guide" class="btn flat sm">Hướng dẫn chi tiết ↗</button></div><div class="steps redesigned-steps"><div class="step-card"><span class="step-num">01</span><div class="step-icon">↗</div><h3>Gửi link bạn thích</h3><p>Dán link Taobao, chọn phân loại, số lượng và thêm vào giỏ.</p></div><div class="step-card"><span class="step-num">02</span><div class="step-icon">¥</div><h3>Nhận báo giá</h3><p>Tura kiểm tra sản phẩm và gửi tổng chi phí rõ ràng.</p></div><div class="step-card"><span class="step-num">03</span><div class="step-icon">♡</div><h3>Xác nhận đặt hộ</h3><p>Duyệt báo giá rồi xác nhận thanh toán theo hướng dẫn.</p></div><div class="step-card"><span class="step-num">04</span><div class="step-icon">▣</div><h3>Theo dõi hành trình</h3><p>Biết được đơn hàng đã đến chặng nào trên đường về.</p></div></div></section><section class="content-section sample-section"><div class="section-head"><div><div class="section-label">Thử ngay trên web</div><h2>Một vài món xinh để thử</h2><p>Giá ¥ kèm mức quy đổi ≈ VND theo tỷ giá demo (1 ¥ ≈ ${fmt(db.settings.rate)}), chưa gồm phí.</p></div><span class="section-pill">✳ Dữ liệu minh họa</span></div><div class="sample-grid">${P.map(p=>`<button class="sample-card" data-sample="${p.id}"><div class="product-tile">${p.emoji}</div><div><h3>${safe(p.name)}</h3><p>${safe(p.kind)}</p>${priceTag(p.price,'sample-price')}</div><span class="sample-next">↗</span></button>`).join('')}</div></section><section class="contact-section" id="support"><div class="contact-main"><div class="contact-topline"><span class="contact-glint">✦</span> Tura luôn ở đây</div><h2>Cần Tura giúp<br><em>một tay?</em></h2><p>Thắc mắc về cách đặt hàng, báo giá hoặc vận chuyển? Bạn có thể tìm Tura qua các kênh hỗ trợ khi được công bố.</p><button class="contact-guide" data-go="guide">Xem hướng dẫn trước <span aria-hidden="true">↗</span></button></div><div class="contact-social"><div class="contact-social-head"><strong>Kết nối với Tura</strong><span>Các kênh chính thức</span></div>${socialCard('facebook','Facebook','Nhắn tin cho Tura','f')}${socialCard('instagram','Instagram','Theo dõi Tura','◎')}<small class="contact-disclaimer">Liên kết sẽ được hiển thị khi Tura cập nhật trong phần quản trị demo.</small></div><div class="contact-bubble bubble-one" aria-hidden="true"></div><div class="contact-bubble bubble-two" aria-hidden="true"></div></section></div>`;}
function cart(){const e=estimation();return `<div class="shell"><div class="page-heading"><div class="section-label">ORDER BY TURA</div><h1>Giỏ hàng của bạn <span class="soft-badge">${db.cart.length} sản phẩm</span></h1><p>Xem lại sản phẩm và gửi yêu cầu để Tura báo giá chính xác.</p></div>${!db.cart.length?`<div class="empty-state"><div class="empty-face">🛒</div><h3>Giỏ hàng đang trống</h3><p>Bắt đầu bằng cách dán một link Taobao, hoặc chọn sản phẩm mẫu.</p><button class="btn" data-go="home">Tìm sản phẩm →</button></div>`:`<div class="two-col"><section class="panel"><div class="row-between"><h3>Danh sách sản phẩm</h3><button class="btn flat sm" data-go="home">+ Thêm sản phẩm</button></div>${db.cart.map(p=>`<article class="cart-item"><div class="product-tile">${safe(p.emoji||'📦')}</div><div><h4>${safe(p.name)}</h4><p>${safe([p.color,p.size].filter(Boolean).join(' • ')||'Chưa chọn phân loại')}</p><div class="unit-price">Đơn giá ${priceTag(p.price)}</div><div class="qty"><button data-qty="minus" data-id="${safe(p.uid)}" aria-label="Giảm số lượng">−</button><small>${p.qty}</small><button data-qty="plus" data-id="${safe(p.uid)}" aria-label="Tăng số lượng">+</button><button class="link-button" data-qty="remove" data-id="${safe(p.uid)}">Xóa</button></div></div><div class="line-price">${priceTag(p.price*p.qty)}</div></article>`).join('')}<div class="section-gap"><h3>Thông tin nhận hàng</h3><form id="checkout-form"><div class="form-grid"><div class="field"><label>Họ và tên *</label><input name="name" placeholder="Nguyễn Minh Anh" required maxlength="80"></div><div class="field"><label>Số điện thoại *</label><input name="phone" type="tel" inputmode="tel" placeholder="09xxxxxxxx" required pattern="[0-9+().\\s-]{9,17}"></div><div class="field full"><label>Địa chỉ nhận hàng *</label><input name="address" placeholder="Số nhà, đường, phường/xã, tỉnh/thành" required maxlength="240"></div><div class="field full"><label>Ghi chú cho Tura (không bắt buộc)</label><textarea name="note" maxlength="500" placeholder="Lưu ý về sản phẩm hoặc thời gian nhận hàng..."></textarea></div></div><div class="form-actions"><button type="submit" class="btn">Gửi yêu cầu mua hộ →</button></div></form></div></section><aside class="panel sticky"><h3>Chi phí dự kiến</h3><div class="alert">Đây là số tiền <b>ước tính</b>. Tura sẽ xác nhận giá, tình trạng hàng và phí trước khi bạn quyết định thanh toán.</div>${moneyRows(e)}<div class="estimate-note">Tỷ giá minh họa: 1 ¥ = ${fmt(db.settings.rate)}. Phí có thể thay đổi theo cân nặng thực tế và chính sách vận chuyển.</div><button class="btn secondary wide" data-go="guide">Quy trình đặt hộ hoạt động thế nào?</button></aside></div>`}</div>`;}
function orders(){const q=ui.ordersQuery.toLowerCase();const matches=db.orders.filter(o=>[o.id,o.customer?.name,o.status].some(x=>String(x||'').toLowerCase().includes(q)));return `<div class="shell"><div class="page-heading"><div class="section-label">Đơn hàng Tura</div><h1>Đơn hàng của tôi</h1><p>Trong bản demo, các đơn chỉ hiển thị trên trình duyệt đang dùng.</p></div><div class="alert info" style="margin-bottom:16px">Bạn có thể mở một đơn để xác nhận báo giá, thông báo đã chuyển khoản và xem cập nhật từ Admin Tura. Các đơn có nhãn “MẪU” chỉ để trải nghiệm.</div><div class="field" style="max-width:450px;margin-bottom:19px"><input id="orders-search" value="${safe(ui.ordersQuery)}" placeholder="Tìm theo mã đơn hoặc tên người nhận..." class="search-input" aria-label="Tìm đơn hàng"></div>${matches.map(o=>`<article class="order-card"><div class="order-card-head"><div><div class="order-id">${safe(o.id)} ${o.sample?'<span class="demo-mark">• Đơn mẫu</span>':''}</div><div class="order-meta">${dateFormat(o.createdAt)} · ${o.items.length} mặt hàng · ${safe(o.customer.name)}</div></div>${status(o.status)}</div><div class="order-card-foot"><div><span class="muted" style="font-size:10px">${o.quote?'Báo giá đã xác nhận':'Chi phí tham khảo'}</span><div><strong>${fmt(o.quote?.total??o.estimate)}</strong></div></div><button class="btn sm" data-order="${safe(o.id)}">Xem hành trình →</button></div></article>`).join('')||`<div class="empty-state"><div class="empty-face">🐼</div><h3>Chưa tìm thấy đơn hàng</h3><p>Hãy tạo một yêu cầu mua hộ mới để bắt đầu theo dõi.</p><button class="btn" data-go="home">Đặt hàng ngay →</button></div>`}</div>`;}
function orderDetail(o){const e=orderMoney(o),latest=o.history[o.history.length-1];return `<div class="shell"><div class="page-heading"><button class="back" data-go="orders">← Quay về danh sách đơn</button><div class="detail-head"><div><div class="section-label">Chi tiết đơn hàng ${o.sample?'· Demo mẫu':''}</div><h2>${safe(o.id)}</h2><p>Đặt lúc ${dateFormat(o.createdAt)} · Cập nhật ${dateFormat(o.updatedAt)}</p></div>${status(o.status)}</div></div><div class="two-col"><div class="detail-stack"><section class="panel"><h3>Hành trình đơn hàng</h3><div class="alert info">${safe(latest.note)}</div>${timeline(o.history)}${o.tracking?`<div class="alert" style="margin-top:17px">Mã vận chuyển nội bộ (demo): <b>${safe(o.tracking)}</b></div>`:''}${o.publicNote?`<p style="font-size:11px;margin:16px 0 0"><b>Lời nhắn từ Tura:</b> ${safe(o.publicNote)}</p>`:''}</section><section class="panel"><h3>Sản phẩm trong đơn</h3>${productRows(o.items)}</section><section class="panel"><h3>Thông tin nhận hàng</h3><div class="money-row"><span>Người nhận</span><strong>${safe(o.customer.name)}</strong></div><div class="money-row"><span>Số điện thoại</span><strong>${safe(o.customer.phone)}</strong></div><p class="muted" style="font-size:11px">${safe(o.customer.address)}</p>${o.customer.note?`<p class="muted" style="font-size:11px">Ghi chú: ${safe(o.customer.note)}</p>`:''}</section></div><aside class="panel sticky"><h3>Chi phí đơn hàng</h3>${o.quote?`<div class="alert info">Tura đã gửi báo giá cho đơn này.</div>`:`<div class="alert">Đơn chưa có báo giá chính thức. Đây chỉ là ước tính.</div>`}${moneyRows(e)}${o.status==='quoted'?`<div class="alert" style="margin-bottom:12px">Kiểm tra báo giá trước khi xác nhận. Việc xác nhận chưa phát sinh thanh toán thật.</div><button class="btn wide" data-customer="accept" data-id="${safe(o.id)}">Đồng ý báo giá →</button><button class="btn flat wide" data-customer="cancel" data-id="${safe(o.id)}">Không tiếp tục đơn này</button>`:''}${o.status==='awaiting_payment'?`<div class="alert" style="margin-bottom:12px">Trong demo, bạn chỉ mô phỏng bước thông báo chuyển khoản. <b>Không chuyển tiền thật.</b></div><button class="btn wide" data-customer="paid" data-id="${safe(o.id)}">Tôi đã chuyển khoản (demo)</button>`:''}${o.status==='needs_info'?`<div class="alert">Tura cần thêm thông tin để tiếp tục xử lý.</div><button class="btn wide" data-customer="info" data-id="${safe(o.id)}">Bổ sung thông tin →</button>`:''}${['new','reviewing','quoted','awaiting_payment'].includes(o.status)?`<div style="text-align:center;margin-top:10px"><button class="link-button" data-customer="cancel" data-id="${safe(o.id)}">Yêu cầu hủy đơn</button></div>`:''}${o.status==='payment_review'?'<div class="alert info">Đã gửi thông báo. Tura sẽ kiểm tra và xác nhận thanh toán trên trang quản trị (demo).</div>':''}<button class="btn secondary wide" style="margin-top:14px" data-go="orders">← Danh sách đơn hàng</button></aside></div></div>`;}
function guide(){return `<div class="shell"><div class="page-heading"><div class="section-label">Hướng dẫn</div><h1>Đặt hộ Taobao cùng Tura</h1><p>Một hành trình rõ ràng từ lúc bạn chọn món đến khi nhận hàng.</p></div><div class="guided">${[['01','Dán link và nhập thông tin','Chọn sản phẩm từ Taobao, Tmall hoặc 1688. Trong bản demo, bạn điền tên, giá CNY và phân loại thủ công.'],['02','Gửi yêu cầu mua hộ','Thêm sản phẩm vào giỏ, nhập thông tin nhận hàng, rồi gửi yêu cầu cho Tura (dữ liệu mock).'],['03','Tura xác nhận báo giá','Admin kiểm tra mặt hàng, điều chỉnh các khoản phí và gửi báo giá để bạn xem trước.'],['04','Duyệt báo giá và thanh toán','Bạn đồng ý báo giá và mô phỏng thông báo đã chuyển khoản. Không phát sinh giao dịch thật.'],['05','Cập nhật vận chuyển','Admin cập nhật các mốc ở Trung Quốc, tuyến về Việt Nam và giao hàng.'],['06','Theo dõi đơn đến khi hoàn tất','Mọi thay đổi đều xuất hiện ở trang chi tiết đơn hàng kèm thời điểm cập nhật.']].map(([n,title,desc])=>`<article class="panel"><div class="guide-num">${n}</div><h3 class="guide-title">${title}</h3><p class="guide-copy">${desc}</p></article>`).join('')}</div><div class="panel section-gap" style="text-align:center"><h3>Có link Taobao rồi?</h3><p class="muted">Gửi link để trải nghiệm thử quy trình đặt hộ.</p><button class="btn" data-go="home">Bắt đầu đặt hàng →</button></div></div>`;}
function modal(){if(!ui.modal)return '';let content='';if(ui.modal.type==='product'){const p=ui.modal.preset||{};const url=ui.modal.url;content=`<div class="modal-head"><div><div class="section-label">Thêm sản phẩm</div><h2>Thông tin món bạn muốn đặt</h2><p>Chưa kết nối Taobao API, vui lòng nhập thông tin để tạo đơn thử.</p></div><button class="icon-button" data-act="close" aria-label="Đóng">×</button></div><form id="add-product"><input type="hidden" name="link" value="${safe(url)}"><div class="alert" style="margin-bottom:17px">Đường dẫn hợp lệ: <span class="mini-code" style="overflow-wrap:anywhere">${safe(url)}</span></div><div class="form-grid"><div class="field full"><label>Tên sản phẩm *</label><input name="name" required maxlength="140" value="${safe(p.name||'')}" placeholder="VD: Túi đeo chéo màu kem"></div><div class="field"><label>Giá sản phẩm (¥) *</label><input type="number" name="price" min="0.01" max="1000000" step="0.01" required value="${p.price??''}" placeholder="39.80"></div><div class="field"><label>Số lượng *</label><input type="number" name="qty" min="1" max="99" step="1" value="1" required></div><div class="field full"><div class="modal-conversion" role="status" aria-live="polite"><span>Tiền hàng ước tính <small>(chưa gồm phí)</small></span><strong id="product-converted">${p.price?priceTag(p.price):'Nhập giá ¥ để xem quy đổi ≈ VND'}</strong><small>1 ¥ ≈ ${fmt(db.settings.rate)} · Tỷ giá demo do Tura cấu hình</small></div></div><div class="field"><label>Màu sắc</label><input name="color" placeholder="VD: Kem" maxlength="70"></div><div class="field"><label>Kích thước / phân loại</label><input name="size" placeholder="VD: Nhỏ / M / L" maxlength="70"></div><div class="field"><label>Cân nặng dự kiến (kg)</label><input name="weight" type="number" min="0" max="100" step="0.01" value="${p.weight??0.3}"></div><div class="field"><label>Biểu tượng minh họa</label><select name="emoji"><option value="📦">📦 Kiện hàng</option><option value="👜" ${p.emoji==='👜'?'selected':''}>👜 Túi xách</option><option value="👕">👕 Quần áo</option><option value="👟">👟 Giày</option><option value="☕" ${p.emoji==='☕'?'selected':''}>☕ Đồ gia dụng</option><option value="🧦" ${p.emoji==='🧦'?'selected':''}>🧦 Phụ kiện</option></select></div><div class="field full"><label>Ghi chú (tùy chọn)</label><textarea name="note" maxlength="500" placeholder="Thông tin shop, yêu cầu đóng gói, v.v."></textarea></div></div><div class="form-actions"><button class="btn secondary" type="button" data-act="close">Hủy</button><button class="btn" type="submit">Thêm vào giỏ →</button></div></form>`;}
if(ui.modal.type==='info'){content=`<div class="modal-head"><div><h2>Bổ sung thông tin cho Tura</h2><p>Admin sẽ nhìn thấy ghi chú mới của bạn trong chi tiết đơn.</p></div><button class="icon-button" data-act="close">×</button></div><form id="extra-info"><input type="hidden" name="id" value="${safe(ui.modal.id)}"><div class="field"><label>Thông tin bổ sung *</label><textarea name="note" required maxlength="500" placeholder="Màu sắc, kích thước hoặc yêu cầu cần xác nhận..."></textarea></div><div class="form-actions"><button class="btn" type="submit">Gửi bổ sung →</button></div></form>`;}
return `<div class="modal-backdrop" data-overlay="1"><div class="modal" role="dialog" aria-modal="true" aria-label="Biểu mẫu">${content}</div></div>`;}
function login(){return `<div class="admin-login-stage"><div class="login-card"><img class="login-mascot" src="./tura-mascot.webp" alt="Mascot Tura: gấu trúc đẩy xe hàng Taobao"><div class="login-overline">TURA · TRANG QUẢN TRỊ</div><h1>Chào mừng quay lại!</h1><p>Đăng nhập để quản lý yêu cầu mua hộ và hành trình đơn hàng.</p><div class="alert">Đây là <b>bản demo</b>: đăng nhập chỉ là mô phỏng, chưa có bảo mật và không nhận đơn thật.</div><form id="admin-login"><div class="field"><label>Tên đăng nhập</label><input name="user" value="admin" required autocomplete="off"></div><div class="field"><label>Mật khẩu demo</label><input type="password" name="pass" value="tura2026" required autocomplete="off"></div><button class="btn wide" type="submit" style="margin-top:10px">Đăng nhập vào Tura →</button></form><div style="text-align:center;margin-top:17px"><button class="link-button" data-go="home">← Trở về trang khách hàng</button></div></div></div>`;}
function adminNav(){const tabs=[['dashboard','Tổng quan'],['orders','Quản lý đơn hàng'],['customers','Khách hàng'],['settings','Cấu hình demo']];return `<div class="admin-shell"><aside class="admin-aside"><a class="brand-link" href="#home" data-go="home"><img src="./logo.svg" alt="ORDER BY TURA"></a><div class="admin-menu">${tabs.map(([k,v])=>`<button data-tab="${k}" class="${ui.adminTab===k?'active':''}">${k==='dashboard'?'◫':k==='orders'?'▦':k==='customers'?'♧':'⚙'} &nbsp;${v}</button>`).join('')}</div><div class="admin-aside-bottom"><b>Chế độ demo</b><br>Mọi dữ liệu nằm trong trình duyệt hiện tại. Không có backend hay đơn hàng thật.</div></aside><main class="admin-main"><header class="admin-header"><div><div class="section-label">TURA CONTROL CENTER · DEMO</div><h1>${{dashboard:'Tổng quan vận hành',orders:'Quản lý đơn hàng',customers:'Khách hàng',settings:'Cấu hình demo'}[ui.adminTab]}</h1><p>Quy trình nhập hàng và vận chuyển được mô phỏng trực quan.</p></div><button class="btn secondary sm" data-act="logout">Đăng xuất ↗</button></header>${adminPage()}</main></div>`;}
function dashboard(){const stats=[['Tổng đơn',db.orders.length],['Cần kiểm tra',db.orders.filter(o=>['new','needs_info','reviewing'].includes(o.status)).length],['Đang vận chuyển',db.orders.filter(o=>['china_shipping','international_shipping','vietnam_warehouse','delivering'].includes(o.status)).length],['Hoàn tất',db.orders.filter(o=>o.status==='completed').length]];return `<div class="admin-stat-grid">${stats.map(([t,v],i)=>`<div class="stat-card"><span>${t}</span><strong style="color:${['#2b2927','#ed6e22','#557ab4','#33846b'][i]}">${v}</strong><em>đơn hàng · dữ liệu mô phỏng</em></div>`).join('')}</div><div class="admin-cols"><div class="panel"><div class="row-between"><h3>Đơn hàng gần đây</h3><button class="btn flat sm" data-tab="orders">Xem tất cả →</button></div>${adminTable(db.orders.slice(0,7))}</div><div><section class="panel"><h3>Quy trình vận hành</h3><div class="admin-kpis"><div class="kpi-row"><span>01 · Khách gửi yêu cầu</span><b>Nhận đơn</b></div><div class="kpi-row"><span>02 · Kiểm tra và báo giá</span><b>Duyệt giá</b></div><div class="kpi-row"><span>03 · Xác nhận thanh toán</span><b>Kiểm tra</b></div><div class="kpi-row"><span>04 · Mua hàng & vận chuyển</span><b>Cập nhật</b></div><div class="kpi-row"><span>05 · Giao và hoàn tất</span><b>Hoàn tất</b></div></div></section><section class="panel section-gap"><h3>Kiểm thử nhanh</h3><p class="muted" style="font-size:11px">Có sẵn hai đơn mẫu để thử cập nhật trạng thái. Bạn cũng có thể tự tạo đơn mới từ trang khách hàng.</p><button data-go="home" class="btn light wide">Mở trang khách hàng →</button></section></div></div>`;}
function adminTable(orders){return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Chi phí</th><th>Trạng thái</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr data-admin-order="${safe(o.id)}"><td><b>${safe(o.id)}</b><small>${o.sample?'Đơn mẫu · ':''}${dateFormat(o.createdAt)}</small></td><td><b>${safe(o.customer.name)}</b><small>${safe(o.customer.phone)}</small></td><td><b>${fmt(o.quote?.total??o.estimate)}</b></td><td>${status(o.status)}</td><td>Chi tiết →</td></tr>`).join('')||'<tr><td colspan="5" style="text-align:center;padding:36px">Chưa có đơn phù hợp.</td></tr>'}</tbody></table></div>`;}
function adminOrders(){const q=ui.adminSearch.toLowerCase();const os=db.orders.filter(o=>(ui.adminFilter==='all'||o.status===ui.adminFilter)&&[o.id,o.customer.name,o.customer.phone].some(t=>String(t||'').toLowerCase().includes(q)));return `<section class="panel"><div class="admin-tools"><input class="search-input" id="admin-search" placeholder="Tìm mã đơn, tên hoặc số điện thoại..." value="${safe(ui.adminSearch)}"><select class="search-input" id="admin-filter"><option value="all">Tất cả trạng thái</option>${Object.entries(stages).map(([s,[label]])=>`<option value="${s}" ${ui.adminFilter===s?'selected':''}>${safe(label)}</option>`).join('')}</select></div>${adminTable(os)}</section>`;}
function adminDetail(o){const can=nextAdmin[o.status]||[];const est=estimation(o.items);const initial={...est,...o.quote};return `<div class="admin-detail"><button class="back" data-act="back-admin">← Danh sách đơn</button><div class="detail-head"><div><div class="section-label">Chi tiết xử lý ${o.sample?'· Đơn mẫu':''}</div><h2>${safe(o.id)}</h2><p>Ngày gửi ${dateFormat(o.createdAt)}</p></div>${status(o.status)}</div><div class="admin-cols"><div><section class="panel"><h3>Sản phẩm & khách hàng</h3>${productRows(o.items)}<hr class="divider"><div class="money-row"><span>Người nhận</span><strong>${safe(o.customer.name)}</strong></div><div class="money-row"><span>Số liên hệ</span><strong>${safe(o.customer.phone)}</strong></div><p class="muted" style="font-size:11px">${safe(o.customer.address)}</p>${o.customer.note?`<div class="alert">Ghi chú khách: ${safe(o.customer.note)}</div>`:''}</section>${['reviewing','quoted'].includes(o.status)?`<section class="panel"><h3>Kiểm tra và gửi báo giá</h3><div class="alert">Báo giá mock, không dùng để thu tiền. Chỉnh chi phí và nhấn “Gửi báo giá” để khách nhìn thấy.</div><form id="quote-form"><input name="id" type="hidden" value="${safe(o.id)}"><div class="form-grid"><div class="field"><label>Tiền hàng quy đổi (đ)</label><input name="products" type="number" min="0" step="1" value="${initial.products}" required></div><div class="field"><label>Phí dịch vụ (đ)</label><input name="service" type="number" min="0" step="1" value="${initial.service}" required></div><div class="field"><label>Ship Trung Quốc (đ)</label><input name="chinaShip" type="number" min="0" step="1" value="${initial.chinaShip}" required></div><div class="field"><label>Vận chuyển về Việt Nam (đ)</label><input name="internationalShip" type="number" min="0" step="1" value="${initial.internationalShip}" required></div><div class="field full"><label>Khoản phí khác (đ)</label><input name="other" type="number" min="0" step="1" value="${initial.other||0}" required></div></div><div class="form-actions"><button class="btn" type="submit">Gửi báo giá cho khách →</button></div></form></section>`:''}<section class="panel"><h3>Lịch sử xử lý</h3>${timeline(o.history)}</section></div><aside><section class="panel"><h3>Thao tác xử lý</h3>${can.map(([code,label])=>`<button class="btn ${code==='awaiting_payment'?'secondary':''} wide" data-transition="${code}" data-id="${safe(o.id)}" style="margin-bottom:8px">${safe(label)} →</button>`).join('')}${o.status==='new'?'<p class="muted" style="font-size:11px">Bắt đầu kiểm tra để mở phần báo giá.</p>':''}${o.status==='reviewing'?'<p class="muted" style="font-size:11px">Sau khi kiểm tra, điền báo giá ở khung bên cạnh.</p>':''}${o.status==='quoted'?'<p class="muted" style="font-size:11px">Chờ khách đồng ý báo giá.</p>':''}${o.status==='awaiting_payment'?'<p class="muted" style="font-size:11px">Chờ khách bấm thông báo đã chuyển khoản ở trang khách.</p>':''}${o.status==='completed'?'<div class="alert info">Đơn đã hoàn tất (demo).</div>':''}${['new','reviewing','needs_info','out_of_stock','buying'].includes(o.status)?`<div style="display:flex;flex-wrap:wrap;gap:7px;margin-top:15px">${o.status!=='needs_info'?`<button class="btn secondary sm" data-transition="needs_info" data-id="${safe(o.id)}">Cần thêm thông tin</button>`:''}${o.status==='reviewing'?`<button class="btn secondary sm" data-transition="out_of_stock" data-id="${safe(o.id)}">Báo hết hàng</button>`:''}${['new','reviewing','needs_info','out_of_stock'].includes(o.status)?`<button class="btn flat sm" data-transition="cancelled" data-id="${safe(o.id)}">Hủy đơn</button>`:''}</div>`:''}</section><section class="panel section-gap"><h3>Vận chuyển & lời nhắn</h3><form id="tracking-form"><input type="hidden" name="id" value="${safe(o.id)}"><div class="field"><label>Mã vận chuyển (mô phỏng)</label><input name="tracking" maxlength="80" value="${safe(o.tracking||'')}" placeholder="VD: CN-123456"></div><div class="field" style="margin-top:12px"><label>Thông báo hiển thị cho khách</label><textarea name="note" maxlength="500" placeholder="Tình trạng mới nhất...">${safe(o.publicNote||'')}</textarea></div><button class="btn secondary wide" style="margin-top:13px" type="submit">Lưu cập nhật</button></form></section><section class="panel section-gap"><h3>Giá trị đơn</h3>${moneyRows(o.quote||{...est,total:o.estimate})}</section></aside></div></div>`;}
function adminCustomers(){const people=new Map();for(const o of db.orders){const k=o.customer.phone;if(!people.has(k))people.set(k,{...o.customer,count:0,spent:0});const p=people.get(k);p.count++;p.spent+=(o.quote?.total??o.estimate);}return `<div class="admin-notice" style="margin-bottom:17px">Dữ liệu khách hàng trong demo được tạo từ các đơn đã lưu. Không có cơ sở dữ liệu hay tài khoản thật.</div><div class="admin-customers">${[...people.values()].map(p=>`<div class="customer-card"><strong>${safe(p.name)}</strong><span>${safe(p.phone)}</span><div class="kpi-row"><span>Số đơn</span><b>${p.count}</b></div><div class="kpi-row"><span>Giá trị tham khảo</span><b>${fmt(p.spent)}</b></div></div>`).join('')}</div>`;}
function adminSettings(){return `<div class="admin-cols"><div><section class="panel"><h3>Cấu hình chi phí mẫu</h3><div class="alert" style="margin-bottom:16px">Các khoản phí chỉ là ví dụ trong bản demo. Báo giá đã gửi không tự thay đổi khi sửa cấu hình.</div><form id="settings-form"><div class="form-grid"><div class="field"><label>Tỷ giá quy đổi (đ / ¥)</label><input type="number" name="rate" required min="1" max="100000" value="${db.settings.rate}"></div><div class="field"><label>Phí dịch vụ mẫu (đ)</label><input type="number" name="service" required min="0" value="${db.settings.service}"></div><div class="field"><label>Ship nội địa Trung Quốc (đ)</label><input type="number" name="chinaShip" required min="0" value="${db.settings.chinaShip}"></div><div class="field"><label>Vận chuyển Trung Quốc – Việt Nam (đ)</label><input type="number" name="internationalShip" required min="0" value="${db.settings.internationalShip}"></div></div><button type="submit" class="btn" style="margin-top:17px">Lưu cấu hình</button></form></section><section class="panel section-gap"><div class="row-between"><h3>Liên hệ & mạng xã hội</h3><span class="soft-badge">Hiển thị ở trang chủ</span></div><p class="muted" style="font-size:11px;margin-bottom:16px">Để trống nếu chưa có kênh chính thức. Website sẽ hiện “Sắp cập nhật” thay vì đưa khách tới link không tồn tại.</p><form id="social-form"><div class="field"><label>Facebook Tura</label><input type="url" name="facebook" placeholder="https://www.facebook.com/ten-trang" value="${safe(db.social?.facebook||'')}"><small>Chấp nhận liên kết HTTPS thuộc facebook.com, fb.com hoặc fb.me.</small></div><div class="field" style="margin-top:12px"><label>Instagram Tura</label><input type="url" name="instagram" placeholder="https://www.instagram.com/ten-tai-khoan" value="${safe(db.social?.instagram||'')}"><small>Chấp nhận liên kết HTTPS thuộc instagram.com.</small></div><button type="submit" class="btn" style="margin-top:18px">Lưu kênh hỗ trợ</button></form></section></div><section class="panel"><h3>Dữ liệu thử nghiệm</h3><img class="settings-mascot" src="./tura-mascot.webp" alt="Gấu Tura đẩy xe hàng"><p class="muted" style="font-size:11px">Có thể khôi phục dữ liệu để trình diễn toàn bộ flow từ đầu.</p><button class="btn secondary wide" data-act="reset">Khôi phục dữ liệu mẫu</button><p class="muted" style="font-size:10px;margin-top:14px">Thao tác này xóa các đơn và link hỗ trợ đã lưu trong trình duyệt.</p></section></div>`;}
function adminPage(){if(ui.adminOrder){const o=findOrder(ui.adminOrder);if(o)return adminDetail(o);ui.adminOrder=null;}if(ui.adminTab==='dashboard')return dashboard();if(ui.adminTab==='orders')return adminOrders();if(ui.adminTab==='customers')return adminCustomers();return adminSettings();}
function route(){let hash=decodeURI(location.hash.slice(1)||'home');if(hash.startsWith('admin')){ui.page='admin';const parts=hash.split('/');if(['dashboard','orders','customers','settings'].includes(parts[1]))ui.adminTab=parts[1];if(parts[2])ui.adminOrder=parts.slice(2).join('/');}
else if(hash.startsWith('order/')){ui.page='order';ui.detail=hash.slice(6);}
else{ui.page=['home','cart','orders','guide'].includes(hash)?hash:'home';ui.detail=null;}
render();}
function render(){const app=$('#app');if(!app)return;if(ui.page==='admin'){app.innerHTML=sessionStorage.getItem(ADMIN_SESSION)==='true'?adminNav():login();return;}const content=ui.page==='home'?home():ui.page==='cart'?cart():ui.page==='orders'?orders():ui.page==='guide'?guide():orderDetail(findOrder(ui.detail)||{...seed().orders[0],id:'Không tìm thấy đơn'});app.innerHTML=header()+`<main>${content}</main>`+footer()+modal();}
function go(page){ui.modal=null;const target=page==='admin'?'admin/dashboard':page;const hash='#'+target;if(location.hash!==hash)location.hash=hash;else{route();window.scrollTo({top:0});} }
function showProduct(link){const url=productUrl(link);if(!url){toast('Vui lòng dán link từ Taobao, Tmall hoặc 1688.');return;}ui.modal={type:'product',url,preset:presetForLink(url)};render();setTimeout(()=>$('.modal input[name="name"]')?.focus(),0);}
function showOrder(id){ui.detail=id;ui.modal=null;location.hash='#order/'+encodeURIComponent(id);}
function adminOpen(id){ui.adminTab='orders';ui.adminOrder=id;location.hash='#admin/orders/'+id;}
function transition(o,code,note){log(o,code,note);render();toast(stages[code]?.[0]||'Đã cập nhật.');}
function confirmDemo(msg){return window.confirm(msg);}
function click(e){const el=e.target.closest('button,[data-admin-order],[data-go]');if(!el)return;
if(el.dataset.go){e.preventDefault();ui.adminOrder=null;go(el.dataset.go);return;}
if(el.dataset.sample){showProduct('https://item.taobao.com/item.htm?id='+el.dataset.sample);return;}
if(el.dataset.act==='close'){ui.modal=null;render();return;}
if(el.dataset.act==='soon'){toast('Kênh '+(el.dataset.channel==='facebook'?'Facebook':'Instagram')+' của Tura sẽ được cập nhật tại đây.');return;}
if(el.dataset.act==='reset'){if(confirmDemo('Xóa toàn bộ dữ liệu demo trong trình duyệt này và khôi phục đơn mẫu?')){db=seed();store();ui.adminOrder=null;go('home');toast('Đã khôi phục dữ liệu mẫu.');}return;}
if(el.dataset.act==='logout'){sessionStorage.removeItem(ADMIN_SESSION);go('home');toast('Đã thoát chế độ quản trị demo.');return;}
if(el.dataset.tab){ui.adminTab=el.dataset.tab;ui.adminOrder=null;location.hash='#admin/'+ui.adminTab;return;}
if(el.dataset.adminOrder){adminOpen(el.dataset.adminOrder);return;}
if(el.dataset.act==='back-admin'){ui.adminOrder=null;location.hash='#admin/orders';return;}
if(el.dataset.order){showOrder(el.dataset.order);return;}
if(el.dataset.qty){const p=db.cart.find(x=>x.uid===el.dataset.id);if(!p)return;if(el.dataset.qty==='remove')db.cart=db.cart.filter(x=>x.uid!==p.uid);if(el.dataset.qty==='plus')p.qty=Math.min(99,p.qty+1);if(el.dataset.qty==='minus')p.qty=Math.max(1,p.qty-1);store();render();return;}
if(el.dataset.customer){const o=findOrder(el.dataset.id);if(!o)return;
 if(el.dataset.customer==='accept'&&o.status==='quoted'){transition(o,'awaiting_payment','Khách đồng ý báo giá. Chờ thanh toán (mô phỏng).');return;}
 if(el.dataset.customer==='paid'&&o.status==='awaiting_payment'){if(!confirmDemo('Xác nhận đã thông báo chuyển khoản? Đây chỉ là thao tác mô phỏng, không gửi tiền thật.'))return;o.payment='pending';transition(o,'payment_review','Khách thông báo đã chuyển khoản (mô phỏng).');return;}
 if(el.dataset.customer==='cancel'&&['new','reviewing','quoted','awaiting_payment'].includes(o.status)){if(!confirmDemo('Bạn muốn hủy yêu cầu mua hộ này?'))return;transition(o,'cancelled','Khách yêu cầu hủy đơn.');return;}
 if(el.dataset.customer==='info'&&o.status==='needs_info'){ui.modal={type:'info',id:o.id};render();return;}
}
if(el.dataset.transition){const o=findOrder(el.dataset.id),code=el.dataset.transition;if(!o)return;const allowed=(nextAdmin[o.status]||[]).some(([s])=>s===code)||code==='needs_info'&&['new','reviewing','buying'].includes(o.status)||code==='out_of_stock'&&o.status==='reviewing'||code==='cancelled'&&['new','reviewing','needs_info','out_of_stock'].includes(o.status);if(!allowed){toast('Trạng thái này chưa thể chuyển trong bước hiện tại.');return;}if(code==='cancelled'&&!confirmDemo('Hủy đơn này trong bản demo?'))return;transition(o,code,{reviewing:'Tura bắt đầu hoặc tiếp tục kiểm tra sản phẩm.',paid:'Tura xác nhận đã nhận thanh toán (mô phỏng).',buying:'Tura đã bắt đầu mua hàng trên Taobao (mô phỏng).',china_shipping:'Hàng đang được vận chuyển trong Trung Quốc.',international_shipping:'Kiện hàng đang trên đường về Việt Nam.',vietnam_warehouse:'Hàng đã về kho tại Việt Nam.',delivering:'Hàng đang được giao cho người nhận.',completed:'Khách đã nhận hàng, đơn hoàn tất.',needs_info:'Tura cần khách bổ sung thông tin.',out_of_stock:'Sản phẩm đang hết hàng.',cancelled:'Đơn đã bị hủy.'}[code]||'Tura đã cập nhật đơn hàng.');return;}
}
function submit(e){const form=e.target;if(!form.getAttribute('id'))return;e.preventDefault();const f=new FormData(form);const g=k=>String(f.get(k)||'').trim();
if(form.getAttribute('id')==='hero-link'){showProduct(g('link'));return;}
if(form.getAttribute('id')==='add-product'){const price=Number(g('price')),qty=Number(g('qty'));if(!Number.isFinite(price)||price<=0||!Number.isInteger(qty)||qty<1||qty>99){toast('Kiểm tra lại giá và số lượng.');return;}db.cart.push({uid:ID(),name:g('name'),price,qty,color:g('color'),size:g('size'),weight:Number(g('weight'))||0,note:g('note'),emoji:g('emoji'),link:g('link')});store();go('cart');toast('Đã thêm sản phẩm vào giỏ.');return;}
if(form.getAttribute('id')==='checkout-form'){const customer={name:g('name'),phone:g('phone'),address:g('address'),note:g('note')};if(!customer.name||!customer.phone||!customer.address){toast('Vui lòng nhập đầy đủ thông tin nhận hàng.');return;}const est=estimation();const id=ID(),t=now();const order={id,createdAt:t,updatedAt:t,customer,items:clone(db.cart),estimate:est.total,quote:null,status:'new',payment:'unpaid',tracking:'',publicNote:'',history:[{status:'new',note:'Đã gửi yêu cầu. Tura sẽ kiểm tra và báo giá.',at:t}]};db.orders.unshift(order);db.cart=[];store();showOrder(id);toast('Đã tạo yêu cầu mua hộ '+id+' (demo).');return;}
if(form.getAttribute('id')==='admin-login'){if(g('user')==='admin'&&g('pass')==='tura2026'){sessionStorage.setItem(ADMIN_SESSION,'true');ui.adminTab='dashboard';ui.adminOrder=null;location.hash='#admin/dashboard';route();toast('Đăng nhập admin demo thành công.');}else toast('Thông tin demo không đúng. Thử admin / tura2026.');return;}
if(form.getAttribute('id')==='quote-form'){const o=findOrder(g('id'));if(!o||!['reviewing','quoted'].includes(o.status))return;const b={};for(const k of ['products','service','chinaShip','internationalShip','other']){b[k]=Number(g(k));if(!Number.isFinite(b[k])||b[k]<0){toast('Chi phí cần là số không âm.');return;}}b.total=Object.values(b).reduce((a,x)=>a+x,0);o.quote=b;transition(o,'quoted','Tura gửi báo giá '+fmt(b.total)+' để khách xác nhận.');return;}
if(form.getAttribute('id')==='tracking-form'){const o=findOrder(g('id'));if(!o)return;o.tracking=g('tracking');o.publicNote=g('note');o.updatedAt=now();o.history.push({status:o.status,note:'Tura cập nhật thông tin vận chuyển / ghi chú.',at:o.updatedAt});store();render();toast('Đã cập nhật thông tin hiển thị cho khách.');return;}
if(form.getAttribute('id')==='extra-info'){const o=findOrder(g('id'));if(!o||o.status!=='needs_info')return;o.customer.note=[o.customer.note,g('note')].filter(Boolean).join(' | ');ui.modal=null;transition(o,'reviewing','Khách đã bổ sung thông tin: '+g('note'));return;}
if(form.getAttribute('id')==='social-form'){const facebook=g('facebook'),instagram=g('instagram');if((facebook&&!socialUrl(facebook,'facebook'))||(instagram&&!socialUrl(instagram,'instagram'))){toast('Vui lòng nhập link HTTPS Facebook/Instagram chính thức hoặc để trống.');return;}db.social={facebook,instagram};store();render();toast('Đã cập nhật kênh hỗ trợ trên trang chủ.');return;}
if(form.getAttribute('id')==='settings-form'){const s={};for(const k of Object.keys(defaultSettings)){s[k]=Number(g(k));if(!Number.isFinite(s[k])||s[k]<(k==='rate'?1:0)){toast('Cấu hình không hợp lệ.');return;}}db.settings=s;store();render();toast('Đã lưu cấu hình demo.');return;}
}
function change(e){if(e.target.id==='admin-filter'){ui.adminFilter=e.target.value;render();}}
function input(e){if(e.target.closest('#add-product')&&['price','qty'].includes(e.target.name)){const form=e.target.closest('form'),price=Number(form.elements.price.value),qty=Number(form.elements.qty.value);const dest=$('#product-converted');if(dest)dest.innerHTML=price>0&&qty>0?priceTag(price*qty):'Nhập giá ¥ để xem quy đổi ≈ VND';}if(e.target.id==='admin-search'){ui.adminSearch=e.target.value;/* keep keyboard focus and selection */const focus=e.target.selectionStart;render();const input=$('#admin-search');input?.focus();input?.setSelectionRange(focus,focus);}if(e.target.id==='orders-search'){ui.ordersQuery=e.target.value;const focus=e.target.selectionStart;render();const input=$('#orders-search');input?.focus();input?.setSelectionRange(focus,focus);}}
document.addEventListener('click',click);document.addEventListener('submit',submit);document.addEventListener('change',change);document.addEventListener('input',input);
document.addEventListener('click',e=>{if(e.target.dataset.overlay==='1'){ui.modal=null;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;render();}});
window.addEventListener('hashchange',()=>{route();window.scrollTo({top:0});});
window.addEventListener('storage',e=>{if(e.key===KEY){db=load();render();}});
store();route();
})();
